insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo e o julgamento dos crimes previstos nos arts. 33 a 37, se caracterizado ilícito transnacional, são da competência da Justiça Federal. Os crimes praticados nos Municípios que não sejam sede de vara federal serão processados e julgados na vara federal da circunscrição respectiva.', '["Tráfico transnacional (arts. 33 a 37): Justiça Federal.","Município sem vara federal: vara federal da circunscrição."]'::jsonb, '["Competência federal depende da TRANSNACIONALIDADE.","Tráfico interno (sem transnacionalidade) é da Justiça Estadual."]'::jsonb, 'Droga importada do exterior e apreendida em município sem vara federal é julgada na vara federal da circunscrição.', '["Assertiva que atribui à Justiça Federal todo tráfico, ainda que interno, erra: exige ilícito transnacional."]'::jsonb, '[]'::jsonb, '["Art. 40, I"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-70'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Encerrado o processo criminal ou arquivado o inquérito policial, o juiz, de ofício, mediante representação da autoridade de polícia judiciária, ou a requerimento do Ministério Público, determinará a destruição das amostras guardadas para contraprova, certificando nos autos.', '["Fim do processo ou arquivamento do inquérito: destruição das amostras de contraprova.","De ofício, por representação da polícia ou a pedido do MP."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.840, de 2019."]'::jsonb, 'Arquivado o inquérito, o juiz manda destruir as amostras guardadas.', '["Assertiva que mantém as amostras indefinidamente após o fim do processo erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
