insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União poderá estabelecer convênios com os Estados e com o Distrito Federal, visando à prevenção e repressão do tráfico ilícito e do uso indevido de drogas, e com os Municípios, com o objetivo de prevenir o uso indevido e de possibilitar a atenção e reinserção social de usuários e dependentes.', '["Convênios com Estados e DF: prevenção e repressão.","Convênios com Municípios: prevenção, atenção e reinserção."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.219, de 2010.","Com os Municípios, o foco é prevenção e atenção (e não a repressão)."]'::jsonb, 'A União firma convênio com um Município para ações de prevenção.', '["Assertiva que prevê convênio com Municípios para repressão ao tráfico erra: o foco é prevenção, atenção e reinserção."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
