insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Ministério Público, sem prejuízo de outras atribuições, nos casos de violência doméstica e familiar contra a mulher, quando necessário, requisitar força policial e serviços públicos de saúde, de educação, de assistência social e de segurança, entre outros; fiscalizar os estabelecimentos públicos e particulares de atendimento à mulher, adotando de imediato as medidas administrativas ou judiciais cabíveis; e cadastrar os casos de violência doméstica e familiar contra a mulher.', '["Requisitar força policial e serviços públicos.","Fiscalizar estabelecimentos de atendimento à mulher.","Cadastrar os casos de violência."]'::jsonb, '["Três atribuições específicas, sem prejuízo de outras."]'::jsonb, 'O MP fiscaliza uma casa-abrigo e adota medida diante de irregularidade.', '["Assertiva que retira do MP a atribuição de cadastrar os casos de violência doméstica erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em todos os atos processuais, cíveis e criminais, a mulher em situação de violência doméstica e familiar deverá estar acompanhada de advogado, ressalvado o previsto no art. 19 (concessão de medidas protetivas de urgência).', '["Acompanhamento por advogado em todos os atos processuais, cíveis e criminais.","Ressalva: o pedido de medidas protetivas do art. 19."]'::jsonb, '["Para pedir medida protetiva, NÃO é necessário advogado."]'::jsonb, 'A vítima pede a medida protetiva na delegacia, sem advogado, mas é assistida nos demais atos.', '["Assertiva que exige advogado para o pedido de medida protetiva erra: o art. 27 ressalva o art. 19."]'::jsonb, '[]'::jsonb, '["Art. 19","Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É garantido a toda mulher em situação de violência doméstica e familiar o acesso aos serviços de Defensoria Pública ou de Assistência Judiciária Gratuita, nos termos da lei, em sede policial e judicial, mediante atendimento específico e humanizado.', '["Acesso à Defensoria Pública ou à Assistência Judiciária Gratuita.","Em sede policial e judicial.","Atendimento específico e humanizado."]'::jsonb, '["Assistência garantida também na FASE POLICIAL."]'::jsonb, 'A vítima é atendida pela Defensoria Pública já na delegacia.', '["Assertiva que restringe a assistência jurídica à fase judicial erra: abrange a fase policial."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Juizados de Violência Doméstica e Familiar contra a Mulher que vierem a ser criados poderão contar com uma equipe de atendimento multidisciplinar, a ser integrada por profissionais especializados nas áreas psicossocial, jurídica e de saúde.', '["Equipe multidisciplinar nos Juizados.","Áreas psicossocial, jurídica e de saúde."]'::jsonb, '["Faculdade (''poderão contar'')."]'::jsonb, 'O Juizado conta com psicólogos, assistentes sociais e profissionais de saúde.', '["Assertiva que torna obrigatória a equipe multidisciplinar erra: é facultativa."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à equipe de atendimento multidisciplinar, entre outras atribuições, fornecer subsídios por escrito ao juiz, ao Ministério Público e à Defensoria Pública, mediante laudos ou verbalmente em audiência, e desenvolver trabalhos de orientação, encaminhamento, prevenção e outras medidas, voltados para a ofendida, o agressor e os familiares, com especial atenção às crianças e aos adolescentes.', '["Fornecer subsídios por escrito ou verbalmente ao juiz, ao MP e à Defensoria.","Orientação, encaminhamento e prevenção.","Voltados à ofendida, ao agressor e aos familiares, com atenção às crianças e adolescentes."]'::jsonb, '["Atende também o AGRESSOR e os familiares."]'::jsonb, 'A equipe elabora laudo psicossocial para subsidiar a decisão do juiz.', '["Assertiva que restringe o atendimento da equipe à vítima erra: abrange o agressor e os familiares."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-30'
