insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a complexidade do caso exigir avaliação mais aprofundada, o juiz poderá determinar a manifestação de profissional especializado, mediante a indicação da equipe de atendimento multidisciplinar.', '["Caso complexo: juiz pode determinar a manifestação de profissional especializado.","Indicado pela equipe multidisciplinar."]'::jsonb, '["Indicação feita pela equipe multidisciplinar."]'::jsonb, 'O juiz pede avaliação de um psiquiatra indicado pela equipe.', '["Assertiva que dispensa a indicação pela equipe multidisciplinar do profissional especializado erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
