select u.id, u.content_sha256, 'O Poder Judiciário, na elaboração de sua proposta orçamentária, poderá prever recursos para a criação e manutenção da equipe de atendimento multidisciplinar, nos termos da Lei de Diretrizes Orçamentárias.', '["O Judiciário pode prever recursos orçamentários para a equipe multidisciplinar.","Nos termos da Lei de Diretrizes Orçamentárias."]'::jsonb, '["Faculdade."]'::jsonb, 'O tribunal inclui na proposta orçamentária verba para a equipe multidisciplinar.', '["Assertiva que torna obrigatória a previsão de recursos para a equipe multidisciplinar erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
