select u.id, u.content_sha256, 'A instituição dos Juizados de Violência Doméstica e Familiar contra a Mulher poderá ser acompanhada pela implantação das curadorias necessárias e do serviço de assistência judiciária.', '["A instituição dos Juizados pode ser acompanhada de curadorias e assistência judiciária."]'::jsonb, '["Faculdade."]'::jsonb, 'Ao criar o Juizado, o tribunal também implanta serviço de assistência judiciária.', '["Assertiva que torna obrigatória a implantação de curadorias com o Juizado erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
