insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União, o Distrito Federal, os Estados e os Municípios poderão criar e promover, no limite das respectivas competências, centros de atendimento integral e multidisciplinar para mulheres e dependentes; casas-abrigos para mulheres e dependentes menores; delegacias, núcleos de defensoria pública, serviços de saúde e centros de perícia médico-legal especializados; programas e campanhas de enfrentamento da violência; e centros de educação e de reabilitação para os agressores. As campanhas deverão contemplar informações sobre procedimentos e abordagens policiais, prevenção à revitimização, funcionamento das medidas protetivas e mecanismos de monitoração eletrônica.', '["Centros de atendimento integral e multidisciplinar.","Casas-abrigos.","Delegacias, defensoria, saúde e perícia especializados.","Programas e campanhas.","Centros de educação e reabilitação para agressores."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único incluído pela Lei nº 15.383, de 2026 (conteúdo das campanhas).","Faculdade (''poderão'')."]'::jsonb, 'O Município mantém uma casa-abrigo para mulheres e seus filhos.', '["Assertiva que exclui os centros de reabilitação para agressores do rol do art. 35 erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-35'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

